import java.util.LinkedList;
import java.util.Queue;

public class BoundedBufferWaitNotify<T> {
    private final Queue<T> queue = new LinkedList<>();
    private final int capacity;

    public BoundedBufferWaitNotify(int capacity) {
        this.capacity = capacity;
    }

    public void put(T item) throws InterruptedException {
        synchronized (queue) {
            // WHY while: wakeup != predicate true. Spurious wakeups
            // and racing consumers mean we must re-test after re-acquiring.
            while (queue.size() == capacity) {
                queue.wait(); // releases queue lock, parks producer
            }
            queue.add(item);
            // WHY notifyAll: we do not know if waiters are producers or
            // consumers. notify() can wake the wrong type and deadlock.
            queue.notifyAll();
        }
    }

    public T take() throws InterruptedException {
        synchronized (queue) {
            while (queue.isEmpty()) {
                queue.wait(); // releases queue lock, parks consumer
            }
            T item = queue.remove();
            queue.notifyAll(); // buffer changed: re-arm whoever is parked
            return item;
        }
    }
}

import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;

public class BoundedBufferQueue<T> {
    private final BlockingQueue<T> queue;

    public BoundedBufferQueue(int capacity) {
        this.queue = new ArrayBlockingQueue<>(capacity);
    }

    public void put(T item) throws InterruptedException {
        // Blocks when full, handles park/wake, visibility, and
        // re-check internally. No monitor bookkeeping left to get wrong.
        queue.put(item);
    }

    public T take() throws InterruptedException {
        return queue.take(); // blocks when empty
    }
}
